<template>
  <view class="support-page">
    <view class="service-head">
      <view class="service-avatar">行</view>
      <view>
        <b>学徒行在线客服</b>
        <text><i :class="{online:adminOnline}"></i>{{ adminOnline ? '客服当前在线' : '客服暂时离线，消息会保留历史记录' }}</text>
      </view>
      <view class="service-time">09:00-21:00</view>
    </view>

    <scroll-view scroll-y class="message-scroll" :scroll-into-view="scrollTarget">
      <view class="welcome-card">
        <b>你好呀 👋</b>
        <text>路线定制、积分兑换、订单预约都可以在这里问我。图片消息和聊天记录会实时保存。</text>
      </view>
      <view v-for="m in messages" :id="`message-${m.id}`" :key="m.id" class="message-row" :class="m.sender_role">
        <view v-if="m.sender_role==='admin'" class="chat-avatar">行</view>
        <view class="message-main">
          <view class="bubble">
            <template v-if="m.message_type === 'image'">
              <image :src="resolveAssetUrl(m.image_url)" class="chat-image" mode="widthFix" />
              <text v-if="m.content">{{ m.content }}</text>
            </template>
            <template v-else>{{ m.content }}</template>
          </view>
          <text>{{ formatTime(m.created_at) }}</text>
        </view>
        <view v-if="m.sender_role==='user'" class="chat-avatar user">{{ (user?.nickname || '我').slice(0,1) }}</view>
      </view>
      <view v-if="adminTyping" class="typing">客服正在输入 <text>•••</text></view>
      <view id="message-bottom" class="message-bottom"></view>
    </scroll-view>

    <view class="bottom-dock">
      <scroll-view scroll-x class="quick-scroll">
        <view class="quick-list"><view v-for="q in quickQuestions" :key="q" @click="sendQuick(q)">{{ q }}</view></view>
      </scroll-view>
      <view class="composer safe-bottom">
        <view class="tool-btn" @click="pickImage">＋图</view>
        <textarea v-model="content" :disabled="conversation?.status==='closed'" fixed maxlength="2000" placeholder="请输入你想咨询的问题…" @confirm="sendMessage" />
        <view class="send-btn" :class="{disabled:!content.trim()||!connected}" @click="sendMessage">发送</view>
      </view>
    </view>
  </view>
</template>

<script setup>
import { nextTick, ref } from 'vue'
import { onLoad, onUnload } from '@dcloudio/uni-app'
import { createSupportConversation, getCurrentUser, getSupportMessages, getWebSocketBaseUrl, isLoggedIn, resolveAssetUrl, uploadSupportImage } from '../../utils/api.js'

const conversation = ref(null)
const messages = ref([])
const content = ref('')
const connected = ref(false)
const adminOnline = ref(false)
const adminTyping = ref(false)
const scrollTarget = ref('message-bottom')
const user = ref(getCurrentUser())
const quickQuestions = ['积分怎么兑换？', '泰山游怎么预约？', '想人工定制路线', '查询订单进度']

let reconnectTimer = null
let heartbeatTimer = null
let manualClose = false
let connecting = false
let socketTask = null

const scrollBottom = () => nextTick(() => { scrollTarget.value = ''; setTimeout(() => { scrollTarget.value = 'message-bottom' }, 20) })
const formatTime = value => (value ? new Date(value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) : '')
const sendSocket = data => socketTask?.send({ data: JSON.stringify(data) })
const scheduleReconnect = () => {
  clearTimeout(reconnectTimer)
  if (!manualClose) reconnectTimer = setTimeout(connect, 2000)
}

const handleOpen = () => {
  connecting = false
  connected.value = true
  clearInterval(heartbeatTimer)
  heartbeatTimer = setInterval(() => sendSocket({ type: 'ping' }), 25000)
}

const handleMessage = event => {
  let data
  try { data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data } catch { return }
  if (data.type === 'message') {
    if (!messages.value.some(m => m.id === data.message.id)) messages.value.push(data.message)
    scrollBottom()
  } else if (data.type === 'typing' && data.role === 'admin') {
    adminTyping.value = data.typing
  } else if (data.type === 'presence' && data.role === 'admin') {
    adminOnline.value = data.online
  } else if (data.type === 'status' && data.status === 'closed') {
    conversation.value.status = 'closed'
    uni.showToast({ title: '本次客服会话已结束', icon: 'none' })
  }
}

const handleClose = () => {
  connecting = false
  connected.value = false
  socketTask = null
  clearInterval(heartbeatTimer)
  scheduleReconnect()
}

const connect = () => {
  if (!conversation.value || manualClose || connecting || connected.value) return
  connecting = true
  const url = `${getWebSocketBaseUrl()}/support/ws/${conversation.value.id}?user_id=${encodeURIComponent(user.value.user_no)}`
  console.log('[学徒行客服] WebSocket 地址：', url)
  socketTask = uni.connectSocket({
    url,
    timeout: 10000,
    fail: error => {
      console.error('[学徒行客服] WebSocket 创建失败：', error)
      handleClose()
    },
  })
  if (!socketTask) {
    handleClose()
    return
  }
  socketTask.onOpen(handleOpen)
  socketTask.onMessage(handleMessage)
  socketTask.onClose(handleClose)
  socketTask.onError(error => {
    console.error('[学徒行客服] WebSocket 连接失败：', error)
    handleClose()
  })
}

const sendMessage = () => {
  const text = content.value.trim()
  if (!text || !connected.value || conversation.value?.status === 'closed') return
  socketTask.send({
    data: JSON.stringify({ type: 'message', content: text }),
    success: () => { content.value = '' },
    fail: () => uni.showToast({ title: '消息发送失败', icon: 'none' }),
  })
}

const sendQuick = q => { content.value = q; sendMessage() }

const pickImage = () => {
  if (!conversation.value) return
  uni.chooseImage({
    count: 1,
    success: async ({ tempFilePaths }) => {
      try {
        const result = await uploadSupportImage(conversation.value.id, tempFilePaths[0])
        socketTask?.send({
          data: JSON.stringify({ type: 'message', message_type: 'image', image_url: result.url, content: '' }),
        })
      } catch (error) {
        uni.showToast({ title: error.message || '图片上传失败', icon: 'none' })
      }
    },
  })
}

onLoad(async () => {
  if (!isLoggedIn()) {
    uni.redirectTo({ url: '/pages/auth/login' })
    return
  }
  user.value = getCurrentUser()
  try {
    conversation.value = await createSupportConversation()
    adminOnline.value = !!conversation.value.admin_online
    messages.value = await getSupportMessages(conversation.value.id)
    scrollBottom()
    connect()
  } catch (error) {
    uni.showToast({ title: error.message || '客服系统连接失败', icon: 'none' })
  }
})

onUnload(() => {
  manualClose = true
  clearTimeout(reconnectTimer)
  clearInterval(heartbeatTimer)
  socketTask?.close({})
  socketTask = null
})
</script>

